create or replace function public.ui_courses_page(p_limit integer default 50,p_offset integer default 0,p_query text default null,p_country_code text default null,p_level_code text default null,p_lifecycle_status text default null,p_publication_status text default null,p_sort text default 'course',p_direction text default 'asc') returns jsonb language plpgsql stable security definer set search_path='public','catalogue','ref','search','auth' as $$ declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200); v_offset int:=greatest(coalesce(p_offset,0),0); v_sort text:=lower(coalesce(p_sort,'course')); v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end; begin if auth.uid() is null then raise exception 'authentication required'; end if; return (with base as (select c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,sl.code level_code,fos.name field_of_study,c.delivery_mode,coalesce(d.completeness_score,0) completeness_score,coalesce(d.has_fee,false) has_fee,coalesce(d.has_intake,false) has_intake,coalesce(d.has_english,false) has_english,coalesce(d.has_scholarship,false) has_scholarship from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id left join ref.study_levels sl on sl.id=c.study_level_id left join ref.fields_of_study fos on fos.id=c.primary_field_id left join search.course_documents d on d.course_id=c.id where (nullif(trim(coalesce(p_query,'')),'') is null or c.canonical_title ilike '%'||trim(p_query)||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%' or coalesce(c.course_code,'') ilike '%'||trim(p_query)||'%' or coalesce(c.stable_key,'') ilike '%'